#!/usr/bin/env python3
"""Public executable sanity checks, with per-invocation descendant cleanup."""
import argparse
import ctypes
import json
import math
import os
import pathlib
import selectors
import signal
import subprocess
import sys
import time
from candidate_policy import candidate_setup

CANCELLED = 0
CLEANUP_SECONDS = 5

class CheckerInfrastructure(RuntimeError):
    pass

class Interrupted(RuntimeError):
    pass

def remember_signal(signum, frame):
    # Never raise from a signal handler: repeated signals cannot interrupt
    # group termination, waitpid, pipe closure, or reaping adopted descendants.
    global CANCELLED
    if not CANCELLED:
        CANCELLED = signum

def check_interruption():
    if CANCELLED:
        raise Interrupted('public checker interrupted')

def pairs(items):
    obj = {}
    for key, val in items:
        if key in obj:
            raise ValueError('duplicate output key')
        obj[key] = val
    return obj

def nonfinite(value):
    raise ValueError('nonfinite output')

def finite_float(value):
    parsed = float(value)
    if not math.isfinite(parsed):
        raise ValueError('nonfinite output')
    return parsed

def strict_load(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=pairs,
                      parse_constant=nonfinite, parse_float=finite_float)

def same(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def prepare_supervisor():
    if os.uname().machine != 'x86_64':
        raise CheckerInfrastructure('x86_64 worker required')
    libc = ctypes.CDLL(None, use_errno=True)
    if libc.prctl(36, 1, 0, 0, 0):
        raise CheckerInfrastructure('child subreaper unavailable')
    try:
        # Signal 0 changes no process state. A scored-profile parent fails
        # here, before any candidate can inherit inadequate supervision.
        os.killpg(os.getpgrp(), 0)
    except OSError as exc:
        raise CheckerInfrastructure('trusted parent needs published checker profile') from exc

def child_finished(p):
    # WNOWAIT retains the leader's PID until its process group is killed;
    # Popen.poll() would reap it early and lose that group-ID anchor.
    info = os.waitid(os.P_PID, p.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
    return info is not None

def terminate_and_reap(p):
    end = time.monotonic()+CLEANUP_SECONDS
    try:
        os.killpg(p.pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    except OSError as exc:
        raise CheckerInfrastructure('cannot terminate candidate process group') from exc
    try:
        p.wait(timeout=max(.001, end-time.monotonic()))
    except subprocess.TimeoutExpired as exc:
        raise CheckerInfrastructure('candidate leader cleanup deadline') from exc
    while True:
        try:
            pid, _ = os.waitpid(-p.pid, os.WNOHANG)
        except ChildProcessError:
            return
        except InterruptedError:
            continue
        if pid:
            continue
        # Ordinary descendants inherit this group and cannot call setsid or
        # setpgid after candidate_setup. Catch a fork concurrent with the first
        # group signal while a known adopted child still anchors the group.
        try:
            os.killpg(p.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        if time.monotonic() >= end:
            raise CheckerInfrastructure('descendant cleanup deadline')
        time.sleep(.002)

def execute(candidate, data):
    """Actual child pipes; session ownership is established before policy restore."""
    prepare_supervisor()
    check_interruption()
    env = {'PATH': os.environ.get('PATH', '/usr/local/bin:/usr/bin:/bin'),
           'LANG': 'C.UTF-8', 'HOME': '/workspace',
           'TMPDIR': os.environ.get('TMPDIR', '/workspace/tmp'),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONHASHSEED': '0',
           'OPENBLAS_NUM_THREADS': '1', 'OMP_NUM_THREADS': '1', 'MKL_NUM_THREADS': '1'}
    end = time.monotonic()+180
    try:
        p = subprocess.Popen([sys.executable, '-B', str(candidate)], stdin=subprocess.PIPE,
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                             close_fds=True, env=env, start_new_session=True,
                             preexec_fn=candidate_setup)
    except (OSError, subprocess.SubprocessError) as exc:
        raise CheckerInfrastructure('candidate supervision/policy setup failed') from exc
    sel = selectors.DefaultSelector()
    streams = [p.stdin, p.stdout, p.stderr]
    output = [bytearray(), bytearray()]
    pos = 0

    def read_output(f, k):
        cap = (32*1024**2, 1024**2)[k]
        try:
            block = os.read(f.fileno(), min(65536, cap-len(output[k])+1))
        except BlockingIOError:
            return True
        if len(output[k])+len(block) > cap:
            raise ValueError('candidate output limit')
        output[k].extend(block)
        return bool(block)

    try:
        for f in streams:
            os.set_blocking(f.fileno(), False)
        if data:
            sel.register(p.stdin, selectors.EVENT_WRITE, -1)
        else:
            p.stdin.close()
        sel.register(p.stdout, selectors.EVENT_READ, 0)
        sel.register(p.stderr, selectors.EVENT_READ, 1)
        while not child_finished(p):
            check_interruption()
            if time.monotonic() >= end:
                raise ValueError('candidate wall limit')
            for key, _ in sel.select(.05):
                f, k = key.fileobj, key.data
                if k == -1:
                    try:
                        sent = os.write(f.fileno(), data[pos:pos+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(f)
                        f.close()
                        continue
                    pos += sent
                    if pos == len(data):
                        sel.unregister(f)
                        f.close()
                elif not read_output(f, k):
                    sel.unregister(f)
                    f.close()
    finally:
        # This also runs on normal root return with detached descendants,
        # output/deadline rejection, abnormal exit, and all Python exceptions.
        try:
            terminate_and_reap(p)
            # Preserve explicitly written/flushed pipe bytes on os._exit(0).
            # Descendants are gone, so these pipes must reach EOF immediately.
            for k, f in enumerate([p.stdout, p.stderr]):
                if not f.closed:
                    while read_output(f, k):
                        pass
        finally:
            sel.close()
            for f in streams:
                f.close()
    check_interruption()
    if p.returncode != 0:
        raise ValueError('candidate nonzero exit')
    if not output[0].strip():
        raise ValueError('candidate empty output')
    return strict_load(bytes(output[0]))

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--candidate', default='submission/main.py')
    args = parser.parse_args()
    if os.geteuid() == 0:
        print('INFRASTRUCTURE: run this checker as nonroot inside the offline task environment.', file=sys.stderr)
        return 2
    signal.signal(signal.SIGTERM, remember_signal)
    signal.signal(signal.SIGINT, remember_signal)
    candidate = pathlib.Path(args.candidate).resolve()
    here = pathlib.Path(__file__).resolve().parent
    fixtures = json.loads((here/'examples/checks.json').read_text())
    try:
        for i, fixture in enumerate(fixtures):
            check_interruption()
            data = fixture.get('raw')
            if data is None:
                data = json.dumps(fixture['request'], separators=(',', ':'))
            try:
                result = execute(candidate, data.encode('utf-8'))
                if not same(result, fixture['response']):
                    raise ValueError('response mismatch')
            except (ValueError, OSError, RecursionError, OverflowError) as exc:
                check_interruption()
                print(f'FAIL public fixture {i}: {exc}')
                return 1
        check_interruption()
        print(f'PASS {len(fixtures)} public executable checks')
        return 128+CANCELLED if CANCELLED else 0
    except Interrupted:
        print('INTERRUPTED: candidate process group terminated and reaped', file=sys.stderr)
        return 128+CANCELLED
    except CheckerInfrastructure as exc:
        print(f'INFRASTRUCTURE: {exc}', file=sys.stderr)
        return 2

if __name__ == '__main__':
    raise SystemExit(main())
