                    u=sid(i,(delta-1)//h);v=sid(j,(g-delta-1)//h)
                    adj[u].append(v);adj[v].append(u)
        leaves=[lid(gr,lf) for gr in range(g) for lf in range(l)]
        alld=[bfs(adj,x) for x in range(n)]
        pairs=[];dom=[]
        for src in leaves:
