use std::collections::{HashMap, HashSet};

use crate::solver::SolverProblem;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

struct GroupEval {
    delta_count: i64,
    delta_load: i128,
    old_changed_count: u64,
    new_pairs: HashSet<(u64, u64)>,
    cover_delta: Vec<i32>,
}

struct FinalGroup {
    cover: Vec<u32>,
    footprint: Vec<u64>,
    footprint_size: u64,
    count: u64,
    load: u64,
    quota: u64,
    budget: u64,
    pair: Option<(u64, u64)>,
}

#[inline]
fn word_count(n: usize) -> usize { (n + 63) / 64 }

#[inline]
fn count_words(words: &[u64]) -> u64 {
    words.iter().map(|x| x.count_ones() as u64).sum()
}

fn new_eval(n: usize) -> GroupEval {
    GroupEval {
        delta_count: 0,
        delta_load: 0,
        old_changed_count: 0,
        new_pairs: HashSet::new(),
        cover_delta: vec![0i32; n],
    }
}

pub struct Ledger {
    n: usize,
    template_count: usize,
    words: usize,
    task_count: usize,
    group_count_len: usize,
    revision: u64,

    tasks: Vec<Task>,
    quotas: Vec<u64>,
    budgets: Vec<u64>,
    capacities: Vec<u64>,

    template_footprints: Vec<u64>,
    template_domains: Vec<u64>,

    group_counts: Vec<u64>,
    group_loads: Vec<u64>,
    group_pinned_counts: Vec<u64>,
    group_footprints: Vec<u64>,
    group_footprint_sizes: Vec<u64>,
    // Number of member tasks whose template footprint covers each node.
    group_cover: Vec<u32>,
    group_pairs: Vec<Option<(u64, u64)>>,

    usage: Vec<u64>,
    total_usage: u64,
    total_weight: u64,
    total_pinned: u64,
    active_groups: u64,
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let n = problem.num_nodes;
        let template_count = problem.demands.len();
        let group_count_len = quotas.len();
        if budgets.len() != group_count_len || capacities.len() != n {
            return Err("bad vector length".into());
        }
        if group_count_len == 0 {
            return Err("no groups".into());
        }
        let words = word_count(n);

        // A template's domain is its source-domain identifier from the static
        // topology description.  Dragonfly's source-target scope supplies an
        // explicit domain value in demand_merge_classes.
        let mut source_domain = vec![usize::MAX; n];
        for (domain, members) in problem.source_merge_groups.iter().enumerate() {
            for &node in members {
                if node >= n {
                    return Err("source domain node out of range".into());
                }
                if source_domain[node] != usize::MAX {
                    return Err("source node in two domains".into());
                }
                source_domain[node] = domain;
            }
        }

        let mut template_domains = Vec::with_capacity(template_count);
        for (template, demand) in problem.demands.iter().enumerate() {
            let domain = if let Some(classes) = problem.demand_merge_classes.as_ref() {
                *classes
                    .get(template)
                    .ok_or_else(|| "missing demand merge class".to_string())?
                    as u64
            } else {
                if demand.src >= n || source_domain[demand.src] == usize::MAX {
                    return Err("demand source has no domain".into());
                }
                source_domain[demand.src] as u64
            };
            template_domains.push(domain);
        }

        let mut template_footprints = vec![0u64; template_count * words];
        for (template, demand) in problem.demands.iter().enumerate() {
            if demand.footprint.is_empty() {
                return Err("empty template footprint".into());
            }
            let base = template * words;
            for &node in &demand.footprint {
                if node >= n {
                    return Err("template footprint node out of range".into());
                }
                template_footprints[base + node / 64] |= 1u64 << (node % 64);
            }
        }

        let mut group_counts = vec![0u64; group_count_len];
        let mut group_loads = vec![0u64; group_count_len];
        let mut group_pinned_counts = vec![0u64; group_count_len];
        let mut group_footprints = vec![0u64; group_count_len * words];
        let mut group_cover = vec![0u32; group_count_len * n];
        let mut group_pairs: Vec<Option<(u64, u64)>> = vec![None; group_count_len];
        let mut total_weight = 0u64;
        let mut total_pinned = 0u64;

        for (task_id, task) in tasks.iter().enumerate() {
            if task.template >= template_count || task.group >= group_count_len {
                return Err(format!("initial task {} out of range", task_id));
            }
            let g = task.group;
            group_counts[g] = group_counts[g]
                .checked_add(1)
                .ok_or_else(|| "task count overflow".to_string())?;
            group_loads[g] = group_loads[g]
                .checked_add(task.weight)
                .ok_or_else(|| "group load overflow".to_string())?;
            if task.pinned {
                group_pinned_counts[g] += 1;
                total_pinned += 1;
            }
            total_weight = total_weight
                .checked_add(task.weight)
                .ok_or_else(|| "weight overflow".to_string())?;

            let pair = (template_domains[task.template], task.class);
            match group_pairs[g] {
                None => group_pairs[g] = Some(pair),
                Some(previous) if previous != pair => {
                    return Err("initial group is mixed".into())
                }
                _ => {}
            }

            let tf = task.template * words;
            for wi in 0..words {
                let mut bits = template_footprints[tf + wi];
                while bits != 0 {
                    let bit = bits.trailing_zeros() as usize;
                    let node = wi * 64 + bit;
                    group_cover[g * n + node] += 1;
                    bits &= bits - 1;
                }
            }
            let gf = g * words;
            for wi in 0..words {
                group_footprints[gf + wi] |= template_footprints[tf + wi];
                group_footprints[gf + wi] |= template_footprints[tf + wi];
            }
        }

        let mut usage = vec![0u64; n];
        let mut active_groups = 0u64;
        for g in 0..group_count_len {
            if group_counts[g] == 0 {
                continue;
            }
            active_groups += 1;
            if quotas[g] == 0 {
                return Err("active group has zero quota".into());
            }
            let cap_budget = quotas[g]
                .checked_mul(budgets[g])
                .ok_or_else(|| "quota budget overflow".to_string())?;
            if group_loads[g] > cap_budget {
                return Err("initial work exceeds budget".into());
            }
            if group_pairs[g].is_none() {
                return Err("active group has no pair".into());
            }
            let gf = g * words;
            for wi in 0..words {
                let mut bits = group_footprints[gf + wi];
                while bits != 0 {
                    let bit = bits.trailing_zeros() as usize;
                    let node = wi * 64 + bit;
                    usage[node] = usage[node]
                        .checked_add(quotas[g])
                        .ok_or_else(|| "usage overflow".to_string())?;
                    bits &= bits - 1;
                }
            }
        }

        for node in 0..n {
            if usage[node] > capacities[node] {
                return Err("initial capacity exceeded".into());
            }
        }

        let mut group_footprint_sizes = vec![0u64; group_count_len];
        for g in 0..group_count_len {
            group_footprint_sizes[g] =
                count_words(&group_footprints[g * words..(g + 1) * words]);
        }
        let total_usage = usage.iter().copied().sum();

        Ok(Self {
            n,
            template_count,
            words,
            task_count: tasks.len(),
            group_count_len,
            revision: 0,
            tasks,
            quotas,
            budgets,
            capacities,
            template_footprints,
            template_domains,
            group_counts,
            group_loads,
            group_pinned_counts,
            group_footprints,
            group_footprint_sizes,
            group_cover,
            group_pairs,
            usage,
            total_usage,
            total_weight,
            total_pinned,
            active_groups,
        })
    }

    pub fn certificate(&self, query: &Query) -> Certificate {
        let totals = [
            self.active_groups,
            self.total_usage,
            self.total_weight,
            self.total_pinned,
        ];

        let mut groups = Vec::with_capacity(query.groups.len());
        for &g in &query.groups {
            let (domain, class) = match self.group_pairs[g] {
                Some((d, c)) => (d as i64, c as i64),
                None => (-1i64, -1i64),
            };
            groups.push([
                g as i64,
                self.group_counts[g] as i64,
                self.group_loads[g] as i64,
                self.quotas[g] as i64,
                self.budgets[g] as i64,
                self.group_footprint_sizes[g] as i64,
                domain,
                class,
            ]);
        }

        let mut nodes = Vec::with_capacity(query.nodes.len());
        for &node in &query.nodes {
            nodes.push([node as u64, self.usage[node], self.capacities[node]]);
        }

        let mut task_rows = Vec::with_capacity(query.tasks.len());
        for &task_id in &query.tasks {
            let t = self.tasks[task_id];
            task_rows.push([
                task_id as u64,
                t.group as u64,
                t.template as u64,
                t.weight,
                t.class,
                t.pinned as u64,
            ]);
        }

        Certificate {
            totals,
            groups,
            nodes,
            tasks: task_rows,
        }
    }

    pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
        if expected != self.revision {
            return Outcome {
                accepted: false,
                revision: self.revision,
                violations: None,
                certificate: self.certificate(query),
            };
        }

        let mut task_updates: HashMap<usize, Task> = HashMap::new();
        let mut quota_updates: HashMap<usize, u64> = HashMap::new();
        let mut budget_updates: HashMap<usize, u64> = HashMap::new();
        let mut cap_updates: HashMap<usize, u64> = HashMap::new();

        for edit in edits {
            match *edit {
                Edit::Move(task, group) => {
                    let t = task_updates.entry(task).or_insert(self.tasks[task]);
                    t.group = group;
                }
                Edit::Weight(task, weight) => {
                    let t = task_updates.entry(task).or_insert(self.tasks[task]);
                    t.weight = weight;
                }
                Edit::Class(task, class) => {
                    let t = task_updates.entry(task).or_insert(self.tasks[task]);
                    t.class = class;
                }
                Edit::Bind(task, template) => {
                    let t = task_updates.entry(task).or_insert(self.tasks[task]);
                    t.template = template;
                }
                Edit::Pin(task, pinned) => {
                    let t = task_updates.entry(task).or_insert(self.tasks[task]);
                    t.pinned = pinned;
                }
                Edit::Quota(group, quota) => {
                    quota_updates.insert(group, quota);
                }
                Edit::Budget(group, budget) => {
                    budget_updates.insert(group, budget);
                }
                Edit::Cap(node, capacity) => {
                    cap_updates.insert(node, capacity);
                }
            }
        }

        // Repeated assignments are resolved above.  Discard assignments whose
        // final value is the committed value: they cannot affect either the
        // proposal or its certificate.
        task_updates.retain(|&id, task| *task != self.tasks[id]);
        quota_updates.retain(|&g, q| *q != self.quotas[g]);
        budget_updates.retain(|&g, b| *b != self.budgets[g]);
        cap_updates.retain(|&node, capacity| *capacity != self.capacities[node]);

        if task_updates.is_empty()
            && quota_updates.is_empty()
            && budget_updates.is_empty()
            && cap_updates.is_empty()
        {
            // The committed state is legal by induction.
            self.revision += 1;
            return Outcome {
                accepted: true,
                revision: self.revision,
                violations: Some([0, 0, 0, 0]),
                certificate: self.certificate(query),
            };
        }

        // Pin protection uses the task's state at the beginning of this
        // transaction.  A quota change on a protected task's old group affects
        // every pinned task in that group once, without regard to how many of
        // its other protected fields changed.
        let quota_changed: HashSet<usize> = quota_updates.keys().copied().collect();
        let mut pin_violations = 0u64;
        for &g in &quota_changed {
            pin_violations = pin_violations.saturating_add(self.group_pinned_counts[g]);
        }
        for (&task_id, final_task) in &task_updates {
            let old_task = self.tasks[task_id];
            if old_task.pinned {
                let fields_changed = old_task.group != final_task.group
                    || old_task.template != final_task.template
                    || old_task.weight != final_task.weight
                    || old_task.class != final_task.class;
                if fields_changed && !quota_changed.contains(&old_task.group) {
                    pin_violations = pin_violations.saturating_add(1);
                }
            }
        }

        // Only groups with changed task composition/loads or changed quota or
        // budget can contribute mixed/work violations.  The committed state is
        // legal, so every other group is known to have zero such violations.
        let mut affected: HashSet<usize> = HashSet::new();
        for (&task_id, final_task) in &task_updates {
            let old_task = self.tasks[task_id];
            let stats_changed = old_task.group != final_task.group
                || old_task.template != final_task.template
                || old_task.weight != final_task.weight
                || old_task.class != final_task.class;
            if stats_changed {
                affected.insert(old_task.group);
                affected.insert(final_task.group);
            }
        }
        affected.extend(quota_updates.keys().copied());
        affected.extend(budget_updates.keys().copied());

        let mut evals: HashMap<usize, GroupEval> =
            affected.into_iter().map(|g| (g, new_eval(self.n))).collect();

        for (&task_id, final_task) in &task_updates {
            let old_task = self.tasks[task_id];
            let stats_changed = old_task.group != final_task.group
                || old_task.template != final_task.template
                || old_task.weight != final_task.weight
                || old_task.class != final_task.class;
            if !stats_changed {
                continue;
            }

            {
                let ev = evals.get_mut(&old_task.group).unwrap();
                ev.delta_count -= 1;
                ev.delta_load -= old_task.weight as i128;
                ev.old_changed_count += 1;
                if old_task.group != final_task.group || old_task.template != final_task.template {
                    let tf = old_task.template * self.words;
                    for wi in 0..self.words {
                        let mut bits = self.template_footprints[tf + wi];
                        while bits != 0 {
                            let bit = bits.trailing_zeros() as usize;
                            let node = wi * 64 + bit;
                            ev.cover_delta[node] -= 1;
                            bits &= bits - 1;
                        }
                    }
                }
            }

            {
                let ev = evals.get_mut(&final_task.group).unwrap();
                ev.delta_count += 1;
                ev.delta_load += final_task.weight as i128;
                ev.new_pairs.insert((
                    self.template_domains[final_task.template],
                    final_task.class,
                ));
                if old_task.group != final_task.group || old_task.template != final_task.template {
                    let tf = final_task.template * self.words;
                    for wi in 0..self.words {
                        let mut bits = self.template_footprints[tf + wi];
                        while bits != 0 {
                            let bit = bits.trailing_zeros() as usize;
                            let node = wi * 64 + bit;
                            ev.cover_delta[node] += 1;
                            bits &= bits - 1;
                        }
                    }
                }
            }
        }

        let mut node_delta = vec![0i64; self.n];
        let mut final_groups: HashMap<usize, FinalGroup> = HashMap::with_capacity(evals.len());
        let mut mixed_violations = 0u64;
        let mut work_violations = 0u64;
        let mut work_violations = 0u64;

        for (g, ev) in evals {
            let base_cover = &self.group_cover[g * self.n..(g + 1) * self.n];
            let mut cover = Vec::with_capacity(self.n);
            let mut footprint = vec![0u64; self.words];
            let mut footprint_size = 0u64;
            for node in 0..self.n {
                let value = base_cover[node] as i64 + ev.cover_delta[node] as i64;
                debug_assert!(value >= 0);
                let value = value.max(0) as u32;
                cover.push(value);
                if value > 0 {
                    footprint[node / 64] |= 1u64 << (node % 64);
                    footprint_size += 1;
                }
            }

            let count_i = self.group_counts[g] as i64 + ev.delta_count;
            debug_assert!(count_i >= 0);
            let count = count_i.max(0) as u64;
            let load_i = self.group_loads[g] as i128 + ev.delta_load;
            debug_assert!(load_i >= 0);
            let load = load_i.max(0) as u64;

            let quota = quota_updates.get(&g).copied().unwrap_or(self.quotas[g]);
            let budget = budget_updates
                .get(&g)
                .copied()
                .unwrap_or(self.budgets[g]);

            let unaffected = self.group_counts[g].saturating_sub(ev.old_changed_count);
            let mut pairs = ev.new_pairs;
            if unaffected > 0 {
                if let Some(pair) = self.group_pairs[g] {
                    pairs.insert(pair);
                }
            }
            let distinct = pairs.len();
            let pair = if distinct == 1 {
                pairs.into_iter().next()
            } else {
                None
            };
            if distinct > 1 {
                mixed_violations += 1;
            }
            if count > 0 {
                let limit = quota.saturating_mul(budget);
                if quota == 0 || load > limit {
                    work_violations += 1;
                }
            }

            // Capacity usage changes only at the union footprint, and quota is
            // charged exactly once at each such node.
            let gf = g * self.words;
            for node in 0..self.n {
                let old_set = self.group_footprints[gf + node / 64] & (1u64 << (node % 64)) != 0;
                let new_set = cover[node] > 0;
                let old_reservation = if old_set { self.quotas[g] as i64 } else { 0 };
                let new_reservation = if new_set { quota as i64 } else { 0 };
                node_delta[node] += new_reservation - old_reservation;
            }

            final_groups.insert(
                g,
                FinalGroup {
                    cover,
                    footprint,
                    footprint_size,
                    count,
                    load,
                    quota,
                    budget,
                    pair,
                },
            );
        }

        let mut capacity_violations = 0u64;
        for node in 0..self.n {
            let usage_i = self.usage[node] as i64 + node_delta[node];
            debug_assert!(usage_i >= 0);
            let usage = usage_i.max(0) as u64;
            let capacity = cap_updates
                .get(&node)
                .copied()
                .unwrap_or(self.capacities[node]);
            if usage > capacity {
                capacity_violations += 1;
            }
        }

        let violations = [
            capacity_violations,
            mixed_violations,
            work_violations,
            pin_violations,
        ];
        let accepted = violations.iter().all(|&v| v == 0);

        if !accepted {
            // No speculative value was written to self, so every committed
            // value remains intact.
            return Outcome {
                accepted: false,
                revision: self.revision,
                violations: Some(violations),
                certificate: self.certificate(query),
            };
        }

        // Commit the task replacements, including pin-only changes.
        for (&task_id, final_task) in &task_updates {
            let old_task = self.tasks[task_id];
            if old_task.pinned {
                self.group_pinned_counts[old_task.group] -= 1;
            }
            if final_task.pinned {
                self.group_pinned_counts[final_task.group] += 1;
            }
            self.total_weight = self.total_weight - old_task.weight + final_task.weight;
            self.total_pinned = self.total_pinned
                - (old_task.pinned as u64)
                + (final_task.pinned as u64);
            self.tasks[task_id] = *final_task;
        }

        for (g, final_group) in final_groups {
            let was_active = self.group_counts[g] > 0;
            let is_active = final_group.count > 0;
            if !was_active && is_active {
                self.active_groups += 1;
            } else if was_active && !is_active {
                self.active_groups -= 1;
            }

            self.group_counts[g] = final_group.count;
            self.group_loads[g] = final_group.load;
            self.group_footprints[g * self.words..(g + 1) * self.words]
                .copy_from_slice(&final_group.footprint);
            self.group_footprint_sizes[g] = final_group.footprint_size;
            self.group_cover[g * self.n..(g + 1) * self.n]
                .copy_from_slice(&final_group.cover);
            self.group_pairs[g] = final_group.pair;
            self.quotas[g] = final_group.quota;
            self.budgets[g] = final_group.budget;
        }

        for (g, quota) in quota_updates {
            self.quotas[g] = quota;
        }
        for (g, budget) in budget_updates {
            self.budgets[g] = budget;
        }
        for (node, capacity) in cap_updates {
            self.capacities[node] = capacity;
        }

        let mut total_usage = 0u64;
        for node in 0..self.n {
            let value = self.usage[node] as i64 + node_delta[node];
            debug_assert!(value >= 0);
            let value = value.max(0) as u64;
            self.usage[node] = value;
            total_usage += value;
        }
        self.total_usage = total_usage;

        self.revision += 1;
        Outcome {
            accepted: true,
            revision: self.revision,
            violations: Some(violations),
            certificate: self.certificate(query),
        }
    }
}

